from collections import deque

def get_components(grid, color, bg):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] == color:
                queue = deque([(r, c)])
                visited[r][c] = True
                component = []
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                components.append(component)
    return components

def is_single_cell(component):
    return len(component) == 1

def get_component_bbox(component):
    positions = set(component)
    min_r = min(pos[0] for pos in positions)
    max_r = max(pos[0] for pos in positions)
    min_c = min(pos[1] for pos in positions)
    max_c = max(pos[1] for pos in positions)
    return (min_r, max_r + 1, min_c, max_c + 1)

